SELECT current_mode 
FROM user_states 
WHERE user_id = $1;

parameters.jsCode:
// Get the message text from the Telegram trigger
const messageInputText = $input.first().json.request.message

const messageText = messageInputText.toLowerCase().trim();
const ingredientsGreeting = $input.first().json.ingredientsGreeting
const productsGreeting = $input.first().json.productsGreeting
const recipesGreeting = $input.first().json.recipesGreeting


let selectedMode = '';
var responseMessage;

switch (messageText) {
  case 'product':
  case 'products':
    selectedMode = 'PRODUCT';
    responseMessage = productsGreeting;
    break;

  case 'ingredient':
  case 'ingredients':
    selectedMode = 'INGREDIENT';
    responseMessage = ingredientsGreeting;
    break;

  case 'recipe':
  case 'recipes':
    selectedMode = 'RECIPE';
    responseMessage = recipesGreeting;
    break;

  case 'exit':
  case 'main':
  case 'quit':
    selectedMode = 'MAIN';
    responseMessage = 'Returning to *Main Mode*. Standard POS commands active.';
    break;

  default:
    // If it's not a mode-switch command, we keep the current state
    // This allows the message to pass through to the Regex Router
    return [{
      json: {
        isModeSwitch: false,
        text: messageText
      }
    }];
}

// Return the new state data
return [{
  json: {
    isModeSwitch: true,
    newMode: selectedMode,
    response: responseMessage,
    userId: $input.first().json.request[0].user_id
  }
}];
